adapters/handlers/rest/restcompat/wrappers.go L34-42:
func wrapReplicationConfig(rc *models.ReplicationConfig) *replicationConfigOut {
	if rc == nil { return nil }
	return &replicationConfigOut{
		ReplicationConfig: rc,
		AsyncEnabled:      rc.Factor > 1 && !asyncReplicationGloballyDisabled.Load(),
	}
}
flag.go L19-26: asyncReplicationGloballyDisabled mirrors ASYNC_REPLICATION_DISABLED 环境变量。
关键：AsyncEnabled 输出字段完全由 factor>1 AND 全局开关派生，models.ReplicationConfig 本身无 AsyncEnabled 持久字段（grep 全库 AsyncEnabled 仅此两处+输出）——用户 POST 的 asyncEnabled:true 在 body 解析层即被丢弃。
